+function rect(c,x,y,w,h,color){c.fillStyle=color;c.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
+function drawLobby(){const w=innerWidth,h=innerHeight;sceneCanvas.width=Math.ceil(w/2);sceneCanvas.height=Math.ceil(h/2);sc.setTransform(1,0,0,1,0,0);sc.scale(sceneCanvas.width/480,sceneCanvas.height/270);const c=sc;c.clearRect(0,0,480,270);let t=frame*.015;
