+for(let i=0;i<8;i++){let x=i*76-22-cameraX*.17;rect(c,x,78,50,5,'#8b9b7d');rect(c,x+12,68,31,12,'#8b9b7d');rect(c,x+20,61,17,8,'#8b9b7d');}
+rect(c,0,91,480,52,'#758f83');for(let i=0;i<18;i++){let x=(i*41+Math.sin(i*3)*18-cameraX*.32)%520;rect(c,x,100+(i%5)*7,18+(i%4)*4,1,'#9baf9c');}
+rect(c,0,139,480,131,'#8d885d');rect(c,0,139,480,11,'#aa9c69');rect(c,0,151,480,5,'#77774f');for(let i=0;i<50;i++){let x=(i*53-cameraX*.52)%500;rect(c,x,161+(i*29%103),4+(i%3)*3,2,i%2?'#756d4d':'#aaa06a');}
+for(let i=0;i<4;i++){let x=(i*155+36-cameraX*.23)%530-20;rect(c,x,112,26,34,'#5e6754');rect(c,x+4,105,19,10,'#67715a');rect(c,x+7,120,5,8,'#263b38');rect(c,x+17,122,4,5,'#263b38');rect(c,x-4,141,34,4,'#736d4d');}
+function tree(x,y,s){rect(c,x+8*s,y+18*s,5*s,20*s,'#514e37');rect(c,x+2*s,y+14*s,16*s,4*s,'#3e5a42');rect(c,x+4*s,y+8*s,13*s,7*s,'#405f46');rect(c,x+7*s,y+2*s,8*s,7*s,'#526e4e');rect(c,x+9*s,y,5*s,4*s,'#687b51');rect(c,x+3*s,y+10*s,4*s,3*s,'#64724d');}
+for(let i=0;i<16;i++){let x=(i*49-cameraX*.8)%520-20;if(x<82||x>375)tree(x,111+(i%3)*8,.65+(i%3)*.18);}
+function crate(x,y,s){rect(c,x,y,23*s,20*s,'#735438');rect(c,x+2*s,y+2*s,19*s,16*s,'#9a7247');rect(c,x+3*s,y+4*s,17*s,3*s,'#bd9358');rect(c,x+9*s,y+2*s,4*s,16*s,'#755638');rect(c,x+2*s,y+9*s,19*s,3*s,'#755638');rect(c,x+5*s,y+18*s,3*s,3*s,'#554834');rect(c,x+16*s,y+18*s,3*s,3*s,'#554834');}
+crate(77,186,1.3);crate(351,166,.82);crate(381,189,1.02);
+rect(c,421,111,3,44,'#404a3b');rect(c,413,104,19,12,'#202a2a');rect(c,416,107,13,6,'#ed693c');rect(c,419,109,7,2,'#ffd265');
+let bob=Math.sin(t*2)*1.3,px=240+Math.sin(t*.55)*1.6;rect(c,px-17,205,36,5,'#4e4934');rect(c,px-12,209,26,2,'#554e37');
+rect(c,px-9,181+bob,7,25,'#253541');rect(c,px+3,181+bob,7,25,'#34414a');rect(c,px-10,201+bob,9,6,'#1c2929');rect(c,px+2,201+bob,10,6,'#1c2929');rect(c,px-12,205+bob,12,3,'#b46942');rect(c,px+1,205+bob,13,3,'#b46942');
+rect(c,px-13,149+bob,27,34,'#b95737');rect(c,px-16,155+bob,7,22,'#ac4f35');rect(c,px+11,154+bob,7,21,'#b95737');rect(c,px-12,151+bob,24,5,'#e27745');rect(c,px-4,154+bob,5,27,'#273b3c');rect(c,px-13,178+bob,27,5,'#e8ad51');rect(c,px+10,155+bob,9,20,'#53604c');rect(c,px+12,158+bob,7,4,'#a18a52');
+rect(c,px-5,144+bob,10,8,'#ad704e');rect(c,px-10,128+bob,20,19,'#b87954');rect(c,px-12,126+bob,23,7,'#202d32');rect(c,px-8,120+bob,16,8,'#283437');rect(c,px-9,135+bob,20,3,'#df9b5b');rect(c,px-4,135+bob,3,3,'#262525');rect(c,px+4,135+bob,3,3,'#262525');rect(c,px-3,142+bob,7,2,'#714736');
+rect(c,px+14,160+bob,30,4,'#202b2a');rect(c,px+37,158+bob,11,3,'#3b4540');rect(c,px+21,164+bob,13,3,'#293331');rect(c,px+14,158+bob,4,8,'#ae7742');rect(c,px+42,157+bob,2,2,'#f1c364');
