const modalData={agents:{eyebrow:'ESCOLHA SEU AGENTE',title:'Agentes',text:'Cada sobrevivente tem sua própria história.',items:[['🧢','Sentinela','Equilibrado · Selecionado'],['🧑🏽‍🚀','Faísca','Especialista em velocidade'],['🥷','Sombra','Mestre da furtividade']]},arsenal:{eyebrow:'EQUIPAMENTO',title:'Arsenal',text:'Prepare seu kit para a próxima queda.',items:[['🔫','Rifle M4','Equilibrado · 30/120'],['🎯','Fuzil de precisão','Dano alto · 5/40'],['🩹','Kit médico','Recupera 30 HP']]},passe:{eyebrow:'TEMPORADA 07',title:'Passe de batalha',text:'Jogue partidas para ganhar recompensas.',items:[['🎁','Nível 24','Recompensa resgatada'],['🪙','Próximo nível','Faltam 180 XP'],['⚡','Missão semanal','Jogue 5 partidas']]},rewards:{eyebrow:'CAIXA DE SUPRIMENTOS',title:'Recompensas',text:'Suas recompensas estão esperando.',items:[['🎁','Caixa diária','Disponível agora'],['🪙','Bônus de login','Resgatado hoje'],['💎','Passe elite','Novas recompensas']]},friends:{eyebrow:'SUA EQUIPE',title:'Amigos online',text:'Convide alguém para a Ilha do Crepúsculo.',items:[['🟢','PixelRafa','Online · Nv. 31'],['🟢','Luna.exe','Online · Nv. 18'],['⚫','NinjaBR','Offline · há 2h']]},settings:{eyebrow:'PREFERÊNCIAS',title:'Configurações',text:'Ajuste sua experiência de jogo.',items:[['🔊','Áudio','Efeitos e música ligados'],['▣','Gráficos','Pixel perfeito · Alto'],['⌨','Controles','Teclado e mouse']]},help:{eyebrow:'CENTRAL DE AJUDA',title:'Como jogar',text:'Explore o lobby e sobreviva na arena!',items:[['⌖','Mover','WASD ou setas'],['✦','Atirar','Clique ou barra de espaço'],['♥','Sobreviver','Elimine 8 drones']]}};
let modalType='',modalSelected=0;function openModal(type){modalType=type;const d=modalData[type]||modalData.agents;$('#modalEyebrow').textContent=d.eyebrow;$('#modalTitle').textContent=d.title;$('#modalText').textContent=d.text;$('#choiceGrid').innerHTML=d.items.map((it,i)=>`<button class="choice ${i===0?'selected':''}" data-choice="${i}"><span class="emoji">${it[0]}</span><b>${it[1]}</b><small>${it[2]}</small></button>`).join('');modalSelected=0;$('#modal').classList.add('show');$$('.choice').forEach(b=>b.onclick=()=>{$$('.choice').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');modalSelected=+b.dataset.choice});}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2100)}
$$('.nav button').forEach(b=>b.onclick=()=>{if(b.dataset.tab==='LOBBY'){toast('Você já está no lobby!');return}$$('.nav button').forEach(x=>x.classList.toggle('active',x===b));openModal(b.dataset.tab.toLowerCase());});
$$('.icon-card').forEach(b=>b.onclick=()=>openModal(b.dataset.modal));$('#modalClose').onclick=()=>$('#modal').classList.remove('show');$('#modal').onclick=e=>{if(e.target.id==='modal')$('#modal').classList.remove('show')};$('#modalAction').onclick=()=>{if(modalType==='agents'){character=modalSelected;const names=['SENTINELA','FAÍSCA','SOMBRA'];$('.character-label').innerHTML=names[character]+' <span>◆ SOBREVIVENTE ◆</span>';toast(names[character]+' selecionado!')}else if(modalType==='friends')toast(modalSelected===2?'Este amigo está offline.':'Convite enviado!');else if(modalType==='rewards')toast('Recompensa adicionada ao inventário!');else if(modalType==='settings')toast('Preferências salvas!');else toast('Tudo pronto!');$('#modal').classList.remove('show')};
$$('.mode').forEach(b=>b.onclick=()=>{$$('.mode').forEach(x=>x.classList.toggle('active',x===b));selectedMode=b.dataset.mode;toast('Modo '+b.textContent.trim()+' selecionado')});let maps=['Ilha do Crepúsculo','Vale Selvagem','Porto Neon'];$('.map-card').onclick=()=>{$('.map-icon').textContent='⌖';$('#mapName').textContent=maps[(maps.indexOf($('#mapName').textContent)+1)%maps.length]};
$('#playBtn').onclick=()=>startGame();
const gc=$('#gameCanvas'),g=gc.getContext('2d');let game={running:false,player:{x:0,y:0,hp:100},enemies:[],bullets:[],keys:{},kills:0,lastShot:0,hitWait:0,aim:{x:1,y:0},elapsed:0};
function startGame(){game={running:true,player:{x:0,y:0,hp:100},enemies:[],bullets:[],keys:{},kills:0,lastShot:0,hitWait:0,aim:{x:1,y:0},elapsed:0};for(let i=0;i<8;i++){let a=i*Math.PI/4;game.enemies.push({x:Math.cos(a)*220+(Math.random()-.5)*70,y:Math.sin(a)*160+(Math.random()-.5)*60,hp:2,speed:18+Math.random()*12,flash:0})}$('#kills').textContent='0';$('#healthNum').textContent='100';$('#healthBar').style.width='100%';$('#endCard').classList.remove('show');$('#gameScreen').classList.add('active');resizeGame();gameLoop()}
function resizeGame(){const r=Math.min(devicePixelRatio||1,2),w=gc.clientWidth,h=gc.clientHeight;if(gc.width!==Math.round(w*r)||gc.height!==Math.round(h*r)){gc.width=Math.round(w*r);gc.height=Math.round(h*r)}g.setTransform(r,0,0,r,0,0)}
window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' '].includes(k)){e.preventDefault();game.keys[k]=true;if(k===' ')shoot()}if(k==='escape'&&game.running)endGame(false)});window.addEventListener('keyup',e=>game.keys[e.key.toLowerCase()]=false);
gc.addEventListener('pointermove',e=>{const r=gc.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,n=Math.hypot(dx,dy)||1;game.aim={x:dx/n,y:dy/n}});gc.addEventListener('pointerdown',e=>{if(game.running){gc.setPointerCapture?.(e.pointerId);shoot()}});
function shoot(){let now=performance.now();if(!game.running||now-game.lastShot<190)return;game.lastShot=now;let target=game.aim;if(innerWidth<760&&game.enemies.length){let nearest=game.enemies.reduce((a,b)=>Math.hypot(b.x-game.player.x,b.y-game.player.y)<Math.hypot(a.x-game.player.x,a.y-game.player.y)?b:a);let dx=nearest.x-game.player.x,dy=nearest.y-game.player.y,n=Math.hypot(dx,dy)||1;target={x:dx/n,y:dy/n}}game.bullets.push({x:game.player.x+target.x*15,y:game.player.y+target.y*15,vx:target.x*390,vy:target.y*390,life:1.15})}
$('#touchFire').addEventListener('pointerdown',e=>{e.preventDefault();shoot()});$$('.dpad button').forEach(b=>{let k=b.dataset.key;if(!k)return;b.addEventListener('pointerdown',e=>{e.preventDefault();game.keys[k]=true;b.setPointerCapture?.(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>game.keys[k]=false))});

